Item.method_code:
const isDirty = aras.isDirtyEx(window.item);
const { toggleSpinner } = options.getActions();

if (isDirty) {
	const dialogSettings = {
		title: aras.getResource('', 'common.refresh')
	};
	const dialogMessage = aras.getResource('', 'common.discard_confirmationmessage');

	const result = await window.ArasModules.Dialog.confirm(dialogMessage, dialogSettings);
	if (result !== 'ok') {
		return;
	}
}

try {
	toggleSpinner(true);
	await window.onRefresh();
} finally {
	toggleSpinner(false);
}
